import { SceneTheme } from "../../types";
import { HEX_SIZE } from "../../constants";
import { AssetManager } from "../assets";
import { MapConfig } from "../utils";

export class BackgroundRenderer {

    public draw(
        ctx: CanvasRenderingContext2D, 
        width: number, 
        height: number, 
        scene: SceneTheme, 
        mapConfig: MapConfig, 
        globalTime: number
    ): void {
        // 1. Base Gradient & Complex Background
        this.drawComplexBackground(ctx, width, height, scene, globalTime);

        // 2. Atmospheric Fog (Screen Space overlay)
        // Map dimensions in pixels for fog scrolling
        const mapPxW = mapConfig.w * HEX_SIZE * 2;
        const mapPxH = mapConfig.h * HEX_SIZE * 2;
        this.drawAtmosphericFog(ctx, mapPxW, mapPxH, scene, globalTime);
    }

    private drawComplexBackground(ctx: CanvasRenderingContext2D, w: number, h: number, scene: SceneTheme, t: number): void {
        // 1. Base Gradient (Sky + Horizon)
        const bgGrad = ctx.createLinearGradient(0, 0, 0, h);
        bgGrad.addColorStop(0, scene.background); // Sky Top
        bgGrad.addColorStop(0.6, scene.horizon);  // Horizon Line
        bgGrad.addColorStop(1, '#000');           // Below Horizon (Ground blend)
        ctx.fillStyle = bgGrad;
        ctx.fillRect(0, 0, w, h);

        ctx.save();

        // 2. Stars / Nebula (For Space/Ice/Night themes)
        if (scene.id === 'VOID' || scene.id === 'ICE' || scene.id === 'FOREST') {
             // Nebula clouds
             ctx.globalCompositeOperation = 'screen';
             const cloudCount = 3;
             for(let i=0; i<cloudCount; i++) {
                 const x = (Math.sin(i * 1.5 + t * 0.05) * 0.5 + 0.5) * w;
                 const y = (Math.cos(i * 1.2 + t * 0.03) * 0.3 + 0.3) * h;
                 const radius = w * 0.4;
                 const grad = ctx.createRadialGradient(x, y, 0, x, y, radius);
                 grad.addColorStop(0, scene.ambientColor);
                 grad.addColorStop(1, 'transparent');
                 ctx.fillStyle = grad;
                 ctx.globalAlpha = 0.15;
                 ctx.beginPath(); ctx.arc(x, y, radius, 0, Math.PI*2); ctx.fill();
             }

             // Stars
             ctx.fillStyle = '#fff';
             const seed = 123; 
             for(let i=0; i<80; i++) {
                 const sx = (Math.sin(i * seed) * 0.5 + 0.5) * w;
                 const sy = (Math.cos(i * seed * 1.5) * 0.5 + 0.5) * h * 0.8; // Keep stars in upper sky
                 const size = Math.random() * 2;
                 const alpha = Math.sin(t + i) * 0.5 + 0.5;
                 ctx.globalAlpha = alpha * (scene.id === 'VOID' ? 0.8 : 0.4);
                 ctx.beginPath(); ctx.arc(sx, sy, size, 0, Math.PI*2); ctx.fill();
             }
        }

        // 3. Distant Silhouette / Terrain (Mountains)
        if (scene.id === 'FOREST' || scene.id === 'ICE' || scene.id === 'DESERT' || scene.id === 'MAGMA') {
            ctx.globalCompositeOperation = 'source-over';
            ctx.fillStyle = scene.background; // Blend with sky color but darker
            ctx.globalAlpha = 0.5;

            const drawMountainLayer = (speed: number, yOffset: number, roughness: number) => {
                ctx.beginPath();
                ctx.moveTo(0, h);
                for(let x=0; x<=w; x+=20) {
                    // Simple procedural terrain noise
                    const n = Math.sin(x * 0.01 + t * speed) * Math.cos(x * 0.03) * roughness;
                    ctx.lineTo(x, h * 0.6 + yOffset + n);
                }
                ctx.lineTo(w, h);
                ctx.fill();
            };

            // Far Layer
            drawMountainLayer(0.01, 0, 50);
            // Near Layer (Darker)
            ctx.fillStyle = '#000';
            ctx.globalAlpha = 0.3;
            drawMountainLayer(0.02, 50, 30);
        }

        // 4. Special Sky Features
        this.drawSkyFeatures(ctx, w, h, scene, t);

        ctx.restore();
    }

    private drawSkyFeatures(ctx: CanvasRenderingContext2D, w: number, h: number, scene: SceneTheme, t: number) {
        if (scene.bgFeature === 'NONE') return;

        ctx.globalCompositeOperation = 'screen';

        if (scene.bgFeature === 'SKY_RIVER') {
            // --- COSMIC RIVER ---
            const color = scene.ambientColor; // Purple

            // Draw multiple sine waves to simulate a flowing river
            for(let i=0; i<5; i++) {
                const lineWidth = 30 + i * 10;
                const amplitude = 30 + i * 10;
                const phase = t * (0.2 + i * 0.05);
                const yBase = h * 0.3 + i * 20;

                ctx.strokeStyle = color;
                ctx.lineWidth = lineWidth;
                ctx.globalAlpha = 0.1 - (i * 0.01);
                ctx.beginPath();
                for(let x=0; x<=w; x+=10) {
                    const y = yBase + Math.sin(x * 0.005 + phase) * amplitude + Math.cos(x * 0.01 - t*0.5) * 20;
                    if (x===0) ctx.moveTo(x, y);
                    else ctx.lineTo(x, y);
                }
                ctx.stroke();
            }

            // Add particles in the river
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = 0.6;
            for(let i=0; i<20; i++) {
                const prog = (t * 0.1 + i / 20) % 1;
                const x = prog * w;
                const y = h * 0.3 + 50 + Math.sin(x * 0.005 + t * 0.2) * 40;
                ctx.beginPath(); ctx.arc(x, y, Math.random()*2 + 1, 0, Math.PI*2); ctx.fill();
            }

        } else if (scene.bgFeature === 'AURORA') {
            // --- VERTICAL CURTAINS ---
            const colors = ['#34d399', '#22d3ee', '#818cf8']; // Green, Cyan, Indigo

            for(let i=0; i<3; i++) {
                const grad = ctx.createLinearGradient(0, 0, 0, h);
                grad.addColorStop(0, 'transparent');
                grad.addColorStop(0.2, colors[i]);
                grad.addColorStop(0.8, 'transparent');

                ctx.fillStyle = grad;
                ctx.globalAlpha = 0.15;

                const phase = t * 0.5 + i * 2;
                ctx.beginPath();
                ctx.moveTo(0, h);
                for(let x=0; x<=w; x+=20) {
                    const y = h * 0.4 + Math.sin(x * 0.01 + phase) * 100 * Math.sin(x*0.002);
                    ctx.lineTo(x, y);
                }
                ctx.lineTo(w, 0); // Top Right
                ctx.lineTo(0, 0); // Top Left
                ctx.fill();
            }

        } else if (scene.bgFeature === 'CANOPY') {
            // --- GOD RAYS ---
            ctx.globalCompositeOperation = 'overlay';
            const centerX = w * 0.8;
            const centerY = -100;

            const grad = ctx.createRadialGradient(centerX, centerY, 50, centerX, centerY, w);
            grad.addColorStop(0, '#fef08a'); // Yellow light
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.globalAlpha = 0.2;

            // Draw Angular Rays
            for(let i=0; i<6; i++) {
                const angle = Math.PI / 2 + Math.sin(t * 0.2 + i) * 0.2 + (i * 0.3);
                const width = Math.PI / 16;

                ctx.beginPath();
                ctx.moveTo(centerX, centerY);
                ctx.lineTo(centerX + Math.cos(angle - width) * w * 1.5, centerY + Math.sin(angle - width) * w * 1.5);
                ctx.lineTo(centerX + Math.cos(angle + width) * w * 1.5, centerY + Math.sin(angle + width) * w * 1.5);
                ctx.fill();
            }
        } else if (scene.bgFeature === 'HEAT_WAVE') {
            // Rising heat distortion visual
            ctx.fillStyle = '#fca5a5';
            ctx.globalAlpha = 0.05;
            for(let i=0; i<10; i++) {
                const x = (i / 10) * w;
                const height = h * 0.5 + Math.sin(t * 2 + i) * 50;
                const width = w / 10;
                ctx.fillRect(x, h - height, width, height);
            }
        }
    }

    private drawAtmosphericFog(ctx: CanvasRenderingContext2D, mapW: number, mapH: number, scene: SceneTheme, t: number) {
        ctx.save();
        ctx.globalCompositeOperation = 'screen';

        const fogColor = scene.fogColor || '#fff';
        const fogSprite = AssetManager.getFogCloud(fogColor); // Use pre-rendered sprite
        const numClouds = 8;

        for (let i = 0; i < numClouds; i++) {
            // Moving clouds across the map
            const speed = 20;
            const x = ((t * speed + i * (mapW / numClouds)) % (mapW * 1.5)) - mapW * 0.25;
            const y = (Math.sin(i * 123 + t * 0.1) * 0.5 + 0.5) * mapH;
            const size = 300 + Math.sin(i) * 100;

            ctx.globalAlpha = 0.1 + Math.sin(t * 0.5 + i) * 0.05; // Pulse opacity
            ctx.drawImage(fogSprite, x - size/2, y - size/2, size, size * 0.6);
        }

        ctx.restore();
    }
}

import { Agent, GameEngine } from "../game";
import { Camera } from "../renderer"; // Circular dependency? Camera interface should ideally be shared
import { GridSystem } from "../systems/grid";
import { HexUtils } from "../utils";
import { Team } from "../../types";

// Re-define Camera interface locally or import if exported from types
// Assuming it was exported from renderer.ts, we should use that or move Camera to types.
// For now, let's redefine locally to match usage if not easily accessible
export interface RenderCamera {
    x: number;
    y: number;
    zoom: number;
}

export class TacticalRenderer {
    // Hologram Glitch State
    private holoGlitchTimer = 0;
    private lastDirectorTarget = "";

    public update(dt: number, engine: GameEngine) {
        // Hologram Glitch Logic
        if (engine.directorTargetId !== this.lastDirectorTarget) {
            this.lastDirectorTarget = engine.directorTargetId || "";
            this.holoGlitchTimer = 0.3; // Trigger glitch for 0.3s
        }
        if (this.holoGlitchTimer > 0) this.holoGlitchTimer -= dt;
    }

    public drawOverlay(ctx: CanvasRenderingContext2D, engine: GameEngine, highlight: Agent | null, grid: GridSystem, globalTime: number) {
        ctx.save();

        // B. Selected Agent Details (Path & Targets)
        if (highlight && highlight.hp > 0) {
            const hH = grid.getTerrainHeight(highlight.q, highlight.r, engine);
            const startPx = highlight.px;
            const startPy = highlight.py - hH - 30; // Waist height

            // 1. Movement Trajectory
            if (highlight.trajectory.length > 0) {
                ctx.beginPath();
                ctx.moveTo(startPx, startPy);

                highlight.trajectory.forEach(hex => {
                    const p = HexUtils.toPx(hex.q, hex.r, engine.mapConfig);
                    const h = grid.getTerrainHeight(hex.q, hex.r, engine);
                    ctx.lineTo(p.x, p.y - h - 30);
                });

                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.setLineDash([5, 5]); // Dashed Line
                ctx.globalAlpha = 0.6;
                ctx.stroke();
                ctx.setLineDash([]); // Reset
                ctx.globalAlpha = 1.0;

                // Destination Marker
                const dest = highlight.trajectory[highlight.trajectory.length - 1];
                const dP = HexUtils.toPx(dest.q, dest.r, engine.mapConfig);
                const dH = grid.getTerrainHeight(dest.q, dest.r, engine);

                ctx.save();
                ctx.translate(dP.x, dP.y - dH);
                ctx.scale(1, 0.6);
                ctx.beginPath(); ctx.arc(0, 0, 10, 0, Math.PI*2); 
                ctx.fillStyle = '#fff'; ctx.globalAlpha = 0.3; ctx.fill();
                ctx.strokeStyle = '#fff'; ctx.globalAlpha = 0.8; ctx.lineWidth=2; ctx.stroke();
                ctx.restore();
            }

            // 2. Target Line
            if (highlight.target && highlight.target.hp > 0) {
                const t = highlight.target;
                const tH = grid.getTerrainHeight(t.q, t.r, engine);
                const endPx = t.px;
                const endPy = t.py - tH - 30;

                const grad = ctx.createLinearGradient(startPx, startPy, endPx, endPy);
                const isEnemy = highlight.team !== t.team;
                const color = isEnemy ? '#ef4444' : '#4ade80';

                grad.addColorStop(0, 'rgba(0,0,0,0)'); // Fade out near source
                grad.addColorStop(0.2, color);
                grad.addColorStop(1, color);

                ctx.beginPath();
                ctx.moveTo(startPx, startPy);
                ctx.lineTo(endPx, endPy);

                ctx.strokeStyle = grad;
                ctx.lineWidth = 2;
                ctx.globalAlpha = 0.8 + Math.sin(globalTime * 10) * 0.2; // Pulse
                ctx.stroke();
                ctx.globalAlpha = 1.0;
            }
        }

        ctx.restore();
    }

    public drawHUD(ctx: CanvasRenderingContext2D, engine: GameEngine, w: number, h: number, cam: RenderCamera, globalTime: number) {
        if (!engine.directorTargetId) return;
        const agent = engine.agents.find(a => a.id === engine.directorTargetId);
        if (!agent) return;

        // Position: Top Right, floating
        const hudX = w - 260; 
        const hudY = 60;
        const width = 240;
        const height = 160;

        ctx.save();

        // --- 1. Glitch Effect ---
        let gx = 0, gy = 0;
        let alphaMod = 1.0;
        if (this.holoGlitchTimer > 0) {
            gx = (Math.random() - 0.5) * 10;
            gy = (Math.random() - 0.5) * 5;
            alphaMod = 0.5 + Math.random() * 0.5;
            if (Math.random() > 0.8) alphaMod = 0.2; // Flicker out
        }

        // --- 2. Perspective Transform ---
        // matrix(1, 0, -0.15, 1, x, y)
        ctx.transform(1, 0, -0.15, 1, hudX + gx, hudY + gy);

        // --- 3. Glass Background ---
        const bgGrad = ctx.createLinearGradient(0, 0, width, height);
        const baseColor = agent.team === Team.BLUE ? '#06b6d4' : '#f97316'; // Cyan vs Orange

        bgGrad.addColorStop(0, `${baseColor}40`); // 25% opacity
        bgGrad.addColorStop(1, `${baseColor}05`); // 2% opacity

        ctx.fillStyle = bgGrad;
        ctx.globalAlpha = alphaMod;
        ctx.fillRect(0, 0, width, height);

        // Grid Lines
        ctx.strokeStyle = `${baseColor}30`;
        ctx.lineWidth = 1;
        ctx.beginPath();
        for(let i=0; i<=width; i+=20) { ctx.moveTo(i, 0); ctx.lineTo(i, height); }
        for(let i=0; i<=height; i+=20) { ctx.moveTo(0, i); ctx.lineTo(width, i); }
        ctx.stroke();

        // Border corners
        ctx.strokeStyle = baseColor;
        ctx.lineWidth = 2;
        const len = 15;
        ctx.beginPath();
        ctx.moveTo(0, len); ctx.lineTo(0, 0); ctx.lineTo(len, 0); // TL
        ctx.moveTo(width-len, 0); ctx.lineTo(width, 0); ctx.lineTo(width, len); // TR
        ctx.moveTo(width, height-len); ctx.lineTo(width, height); ctx.lineTo(width-len, height); // BR
        ctx.moveTo(len, height); ctx.lineTo(0, height); ctx.lineTo(0, height-len); // BL
        ctx.stroke();

        // --- 4. Content: Logic Visualization ---

        // Header
        ctx.fillStyle = baseColor;
        ctx.font = 'bold 12px monospace';
        ctx.fillText(`TARGET: ${agent.id}`, 10, 20);
        ctx.font = '10px monospace';
        ctx.fillStyle = '#fff';
        ctx.fillText(`STATUS: ${agent.btStatus.toUpperCase()}`, 10, 35);

        // Logic Graph
        // [SCAN] -> [DECISION] -> [ACTION]
        const nodes = [
            { x: 30, y: 80, label: 'SCAN', active: true }, // Always active
            { x: 100, y: 80, label: 'THINK', active: agent.btStatus !== '待機' },
            { x: 170, y: 80, label: 'ACT', active: agent.castingSkillIdx !== -1 || agent.isMoving }
        ];

        // Draw Connections
        ctx.strokeStyle = `${baseColor}60`;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(nodes[0].x, nodes[0].y);
        ctx.lineTo(nodes[2].x, nodes[2].y);
        ctx.stroke();

        // Draw Active Flow (Pulse)
        const flowTime = (globalTime * 3) % 1; 
        const flowX = 30 + flowTime * 140;
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(flowX, 80);
        ctx.lineTo(flowX + 15, 80);
        ctx.stroke();

        // Draw Nodes
        nodes.forEach(n => {
            const isActive = n.active;

            // Outer Ring
            ctx.strokeStyle = isActive ? baseColor : `${baseColor}40`;
            ctx.fillStyle = `${baseColor}10`;
            ctx.beginPath(); ctx.arc(n.x, n.y, 10, 0, Math.PI*2); 
            ctx.fill(); ctx.stroke();

            // Inner Dot
            if (isActive) {
                ctx.fillStyle = '#fff';
                ctx.shadowColor = baseColor; ctx.shadowBlur = 10;
                ctx.beginPath(); ctx.arc(n.x, n.y, 4, 0, Math.PI*2); ctx.fill();
                ctx.shadowBlur = 0;
            }

            // Label
            ctx.fillStyle = isActive ? '#fff' : `${baseColor}60`;
            ctx.textAlign = 'center';
            ctx.fillText(n.label, n.x, n.y + 22);
        });

        // Special Alert: ULTIMATE
        if (agent.castingSkillIdx !== -1 && agent.skills[agent.castingSkillIdx]?.tag === 'ULT') {
            ctx.fillStyle = '#ef4444';
            ctx.globalAlpha = (0.5 + Math.sin(globalTime * 20) * 0.5) * alphaMod;
            ctx.fillRect(0, 130, width, 20);
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = 1.0 * alphaMod;
            ctx.font = 'bold 12px monospace';
            ctx.textAlign = 'center';
            ctx.fillText('WARNING: ULTIMATE DETECTED', width/2, 144);
        } else if (agent.hp < agent.maxHp * 0.3) {
            ctx.fillStyle = '#ef4444';
            ctx.font = 'bold 10px monospace';
            ctx.fillText('CRITICAL CONDITION', width - 70, 20);
        }

        // --- 5. Tether Line to Unit ---
        ctx.beginPath();
        ctx.moveTo(10, height);
        ctx.lineTo(10, height + 20);
        ctx.strokeStyle = `${baseColor}40`;
        ctx.setLineDash([2, 4]);
        ctx.stroke();
        ctx.setLineDash([]);

        ctx.restore();
    }

    public drawDebug(ctx: CanvasRenderingContext2D, fps: number): void {
        ctx.fillStyle = 'rgba(255,255,255,0.5)'; 
        ctx.font = '10px monospace';
        ctx.fillText(`FPS: ${fps}`, 10, 20);
    }
}

import { Agent, GameEngine } from "./game";
import { HexUtils } from "./utils";
import { SpriteManager } from "./sprites";
import { Hex, GameEvent, Skill, Team } from "../types";
import { UNIT_VISUAL_HEIGHT, HUD_PADDING } from "../constants";

// Sub-systems
import { GridSystem, RenderableItem } from "./systems/grid";
import { VFXSystem } from "./systems/vfx";
import * as VFXSpawners from "./systems/vfx/spawners"; 
import { VFXRenderer } from "./systems/vfx/render";
import { UnitRenderSystem } from "./systems/unit";
import { HUDSystem } from "./systems/hud";

// NEW Renderers
import { BackgroundRenderer } from "./renderers/background";
import { TacticalRenderer } from "./renderers/tactical";

// Constants
const HUD_TEXT_OFFSET = UNIT_VISUAL_HEIGHT + HUD_PADDING + 20; 
const OBSTACLE_Z_INDEX = 10;
const OBSTACLE_OFFSET_Y = 86; 

export interface Camera {
    x: number;
    y: number;
    zoom: number;
}

export class GameRenderer {
    public globalTime: number = 0;

    // Sub-systems
    public grid: GridSystem;
    public vfx: VFXSystem;
    private vfxRenderer: VFXRenderer;
    public unit: UnitRenderSystem;
    public hud: HUDSystem;

    // New Composition Renderers
    private backgroundRenderer: BackgroundRenderer;
    private tacticalRenderer: TacticalRenderer;

    // Camera Shake Effects
    private shakeTimer = 0; 
    private shakeIntensity = 0;

    // Transition State
    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor() {
        this.grid = new GridSystem();
        this.vfx = new VFXSystem();
        this.vfxRenderer = new VFXRenderer();
        this.unit = new UnitRenderSystem();
        this.hud = new HUDSystem();

        // Initialize sub-renderers
        this.backgroundRenderer = new BackgroundRenderer();
        this.tacticalRenderer = new TacticalRenderer();
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    // --- Core Accessors ---

    public getTerrainHeight(q: number, r: number, engine: GameEngine): number {
        return this.grid.getTerrainHeight(q, r, engine);
    }

    public getHexAtScreenPoint(mouseX: number, mouseY: number, camera: Camera, engine: GameEngine): Hex | null {
        return this.grid.getHexAtScreenPoint(mouseX, mouseY, camera, engine);
    }

    // --- Update Loop ---

    public update(dt: number, engine: GameEngine): void {
        this.globalTime += dt;
        if (this.shakeTimer > 0) {
            this.shakeTimer -= dt;
        }

        // Delegate updates
        this.tacticalRenderer.update(dt, engine);
        this.vfx.update(dt, this.globalTime, engine.currentScene.ambientType);
        this.hud.update(dt);
    }

    public processEventsWithEngine(events: GameEvent[], engine: GameEngine): void {
        events.forEach(event => {
            const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
            const terrainHeight = this.grid.getTerrainHeight(hex.q, hex.r, engine);
            const visualY = event.pos.y - terrainHeight;

            // 1. HUD Events (Floating Text)
            if (['DAMAGE', 'HEAL', 'CC_APPLIED'].includes(event.type)) {
                 const baseY = visualY - HUD_TEXT_OFFSET; 

                 let text = "";
                 let color = "#fff";
                 let size = 16;
                 let type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' = 'DAMAGE';
                 let xOffset = 0;

                 if (event.type === 'DAMAGE') {
                     const val = Math.abs(event.value || 0);
                     text = val.toString();
                     color = val > 100 ? '#ef4444' : '#fff'; 
                     size = val > 100 ? 24 : 16;
                     type = 'DAMAGE';
                     xOffset = (Math.random() - 0.5) * 10;
                 } else if (event.type === 'HEAL') {
                     text = "+" + Math.abs(event.value || 0);
                     color = '#4ade80';
                     type = 'HEAL';
                     xOffset = (Math.random() - 0.5) * 10;
                 } else {
                     text = event.text || "";
                     color = event.color || "#fff";
                     type = 'CC';
                     size = 14;
                     xOffset = -45;
                 }

                 if (text) {
                     this.hud.addFloatingText(event.pos.x + xOffset, baseY, text, color, size, type);
                 }

            } else if (event.type === 'CAST_START') {
                 if (event.skill && event.skill.tag !== 'BASIC') {
                     const isUlt = event.skill.tag === 'ULT';
                     const baseY = visualY - HUD_TEXT_OFFSET - (isUlt ? 30 : 10); 
                     const xOffset = 55; 
                     this.hud.addFloatingText(event.pos.x + xOffset, baseY, event.skill.name, event.skill.color, 14, 'SHOUT', isUlt);
                 }
            } else if (event.type === 'CAST_FINISH') {
                 if (event.skill && event.skill.tag === 'ULT') {
                     if (event.skill.projectileSpeed === 0 || event.skill.power <= 0) {
                         VFXSpawners.spawnDomainExpansion(this.vfx, event.pos.x, event.pos.y, event.skill.color, 4.0);
                         this.triggerCameraShake(0.5, 8); 
                     }
                 }
            }

            // 2. VFX Handling
            switch (event.type) {
                case 'DAMAGE': 
                    const isHeavy = Math.abs(event.value || 0) > 50;
                    VFXSpawners.spawnExplosion(this.vfx, event.pos.x, visualY - 20, 0, 5, event.color || '#fff', 1.0, 0.8, 'SPARK');

                    if (isHeavy) {
                        this.triggerCameraShake(0.2, 5); 
                        VFXSpawners.spawnDebris(this.vfx, event.pos.x, visualY - 20, event.color || '#fff', 3);
                    }
                    break;

                case 'VISUAL_BEAM':
                    if (event.sourceId) {
                        const source = engine.agents.find(a => a.id === event.sourceId);
                        if (source) {
                            const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                            const sH = this.grid.getTerrainHeight(sHex.q, sHex.r, engine);
                            const sx = source.px;
                            const sy = source.py - sH - 40; 

                            const tx = event.pos.x;
                            const ty = visualY - 20; 

                            VFXSpawners.spawnBeam(this.vfx, sx, sy, tx, ty, event.color || '#fff');
                            VFXSpawners.spawnExplosion(this.vfx, tx, ty, 0, 8, event.color || '#fff', 0.5, 0.5, 'SPARK');
                        }
                    }
                    break;

                case 'PROJECTILE_HIT': 
                    this.handleHitVisuals(event, engine, visualY); 
                    break;

                case 'DEATH':
                    const team = event.team !== undefined ? event.team : Team.BLUE; 
                    VFXSpawners.spawnUnitShatter(this.vfx, event.pos.x, visualY, team);
                    this.triggerCameraShake(0.3, 10);
                    break;

                case 'SPAWN':
                    VFXSpawners.spawnTeleport(this.vfx, event.pos.x, visualY, event.color || '#fff');
                    break;
            }
        });
    }

    private handleHitVisuals(event: GameEvent, engine: GameEngine, visualY: number): void {
        const color = event.skill?.color || '#fff';
        const isUlt = event.skill?.tag === 'ULT';

        if (isUlt) {
            this.triggerCameraShake(0.6, 15); 
            VFXSpawners.spawnDivinePillar(this.vfx, event.pos.x, visualY, color, 1.5);
            VFXSpawners.spawnShockwave(this.vfx, event.pos.x, visualY, color, 2.0);

            if (event.skill?.type === 'AOE') {
                const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                const radius = event.skill.aoeRadius || 1;
                const affectedHexes = HexUtils.range(centerHex, radius);

                affectedHexes.forEach(h => {
                    if (engine.isValid(h.q, h.r)) {
                        const tileH = this.grid.getTerrainHeight(h.q, h.r, engine);
                        const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                        const tileVisualY = tilePos.y - tileH;

                        const distToCenter = Math.abs(h.q - centerHex.q) + Math.abs(h.r - centerHex.r);
                        if (distToCenter > 0) {
                            const delay = distToCenter * 0.05;
                            VFXSpawners.spawnDivinePillar(this.vfx, tilePos.x, tileVisualY, color, 0.7, delay);
                            VFXSpawners.addGridFlash(this.vfx, h.q, h.r, color);
                        } else {
                            VFXSpawners.addGridFlash(this.vfx, h.q, h.r, color);
                        }
                    }
                });
            } else {
                VFXSpawners.addImpact(this.vfx, event.pos.x, visualY, color, 'RING', 3.0);
                VFXSpawners.spawnExplosion(this.vfx, event.pos.x, visualY, 0, 50, color, 2.0, 1.0, 'SPARK');
            }
        } else {
            if (event.skill?.type === 'AOE') {
                const center = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                const radius = event.skill.aoeRadius || 1;
                HexUtils.range(center, radius).forEach(h => {
                    if (engine.isValid(h.q, h.r)) {
                        VFXSpawners.addGridFlash(this.vfx, h.q, h.r, color);
                        if (h.q === center.q && h.r === center.r) {
                            VFXSpawners.addDecal(this.vfx, event.pos.x, visualY, color);
                        }
                    }
                });
                VFXSpawners.addImpact(this.vfx, event.pos.x, visualY, color, 'RING', 1.2);
            } else {
                VFXSpawners.addImpact(this.vfx, event.pos.x, visualY, color, 'RING', 0.8);
                VFXSpawners.spawnExplosion(this.vfx, event.pos.x, visualY, 0, 8, color, 1.2, 0.6, 'SPARK');
            }
        }
    }

    private triggerCameraShake(duration: number, intensity: number) {
        this.shakeTimer = duration;
        this.shakeIntensity = intensity;
    }

    // --- Main Rendering Loop ---

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null
    ): void {
        const { width: canvasWidth, height: canvasHeight } = ctx.canvas;
        const scene = engine.currentScene;
        const defaultStyle = scene.obstacleStyle || 'WALL'; 

        // 1. Complex Background (Delegated)
        ctx.clearRect(0, 0, canvasWidth, canvasHeight);
        this.backgroundRenderer.draw(ctx, canvasWidth, canvasHeight, scene, engine.mapConfig, this.globalTime);

        // 2. Camera Transform application
        ctx.save();

        let shakeOffsetX = 0;
        let shakeOffsetY = 0;
        if (this.shakeTimer > 0) {
            shakeOffsetX = (Math.random() - 0.5) * this.shakeIntensity;
            shakeOffsetY = (Math.random() - 0.5) * this.shakeIntensity;
        }

        ctx.translate(canvasWidth / 2 + shakeOffsetX, canvasHeight / 2 + shakeOffsetY);
        ctx.scale(camera.zoom, camera.zoom);
        ctx.translate(-camera.x - canvasWidth / 2 / camera.zoom, -camera.y - canvasHeight / 2 / camera.zoom);

        // 3. MAIN PASS: Collect and Sort Renderables
        let renderList: RenderableItem[] = [];

        renderList.push(...this.grid.collectRenderables(
            engine, hoveredHex, hoveredSkill, highlight, 
            this.vfx.state.gridFlashes, engine.projectiles,
            this.transitionT, this.transitionPhase,
            this.globalTime
        ));

        renderList.push(...this.vfxRenderer.collectRenderables(
            engine,
            this.vfx,
            (q, r) => this.grid.getTerrainHeight(q, r, engine),
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase
        ));

        renderList.push(...this.unit.collectRenderables(
            engine.agents, (q, r) => this.grid.getTerrainHeight(q, r, engine), this.globalTime, highlight, engine.mapConfig
        ));

        // Iterate over Obstacles
        engine.obstacles.forEach((type, key) => {
             const [q, r] = key.split(',').map(Number);
             const pos = HexUtils.toPx(q, r, engine.mapConfig);

             let visualY = pos.y;
             if (this.transitionPhase !== 'IDLE') {
                 const centerQ = Math.floor(engine.mapConfig.w / 2);
                 const centerR = Math.floor(engine.mapConfig.h / 2);
                 const dist = Math.sqrt((q - centerQ)**2 + (r - centerR)**2);
                 const maxDist = Math.max(engine.mapConfig.w, engine.mapConfig.h) / 2;
                 const d = dist / maxDist;

                 if (this.transitionPhase === 'OUT') {
                    const trigger = d * 0.3;
                    if (this.transitionT > trigger) {
                        const fallT = Math.min(1, (this.transitionT - trigger) * 2.5);
                        visualY += fallT * fallT * fallT * 1000;
                    }
                 } else if (this.transitionPhase === 'IN') {
                    const trigger = d * 0.3;
                    const riseT = Math.max(0, Math.min(1, (this.transitionT - trigger) * 2.5));
                    const easedRise = 1 - Math.pow(1 - riseT, 3);
                    visualY += (1 - easedRise) * 1000;
                 }
             }

             if (visualY < pos.y + 800) {
                 const terrainH = this.grid.getTerrainHeight(q, r, engine);
                 renderList.push({
                     y: visualY, z: OBSTACLE_Z_INDEX,
                     draw: (c) => {
                         const sprite = SpriteManager.getObstacleSprite(type || defaultStyle);
                         c.drawImage(sprite, pos.x - 32, visualY - terrainH - OBSTACLE_OFFSET_Y + 20);
                     }
                 });
             }
        });

        renderList.sort((a, b) => {
            if (Math.abs(a.y - b.y) < 2) return a.z - b.z;
            if (a.z > 50 && b.z <= 50) return 1; 
            if (b.z > 50 && a.z <= 50) return -1;
            return a.y - b.y;
        });

        renderList.forEach(item => item.draw(ctx));

        // 4. Occlusion Pass
        const occludedAgents = this.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.unit.drawSilhouette(
                    ctx, agent, 
                    (q, r) => this.grid.getTerrainHeight(q, r, engine), 
                    this.globalTime,
                    engine.mapConfig
                );
            });
            ctx.restore();
        }

        // 5. Tactical Overlay Lines (World Space) - Delegated
        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.grid, this.globalTime);

        // 6. Top VFX (Delegated to VFX Renderer)
        this.vfxRenderer.drawTopLayerParticles(ctx, this.vfx, scene, engine.mapConfig, this.transitionT, this.transitionPhase);

        // 7. HUD
        this.hud.draw(ctx, engine.agents, (q, r) => this.grid.getTerrainHeight(q, r, engine), engine.mapConfig);

        // 8. Holographic Director HUD (Delegated)
        if (engine.directorTargetId) {
            ctx.restore(); 
            this.tacticalRenderer.drawHUD(ctx, engine, canvasWidth, canvasHeight, camera, this.globalTime);
            ctx.save();
        } else {
            ctx.restore();
            ctx.save();
        }

        ctx.restore(); // Final restore

        // 9. Debug Overlay (Delegated)
        this.tacticalRenderer.drawDebug(ctx, fps);
    }
}

import { Agent, GameEngine } from '../engine/game';
import { GameRenderer } from '../engine/renderer';
import { HexUtils } from '../engine/utils';
import { Team, ToolType, Hex, Skill, GameEvent } from '../types';
import { BLOCK_HEIGHT } from '../constants'; 

interface GameCanvasProps {
    engine: GameEngine;
    tool: ToolType;
    selectedObstacle: string; // New: Specific type
    hpInput: number;
    selectedAgent: Agent | null; 
    hoveredSkill: Skill | null;
    isShowcaseMode: boolean; 
    onSelect: (a: Agent | null) => void;
    onWin: (team: Team) => void;
    winner: Team | null;
    rematch: () => void;
    transitionPhase: 'IDLE' | 'IN' | 'OUT';
}

const GameCanvas: React.FC<GameCanvasProps> = ({ engine, tool, selectedObstacle, hpInput, selectedAgent, hoveredSkill, isShowcaseMode, onSelect, onWin, winner, rematch, transitionPhase }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const wrapperRef = useRef<HTMLDivElement>(null);
    const camera = useRef({ x: 0, y: 0, zoom: 1.0 }); // Adjusted default zoom
    const fpsRef = useRef(60);

    // Instantiate Renderer
    const rendererRef = useRef(new GameRenderer());
    const transitionStartTime = useRef(0);

    // Bridge for Synchronous Redraw (Fixes black flash on resize)
    const drawCurrentFrameRef = useRef<() => void>(() => {});

    // Handle Transition Phase Timing
    useEffect(() => {
        transitionStartTime.current = performance.now();
    }, [transitionPhase]);

    // Interaction State
    const draggedAgentRef = useRef<Agent | null>(null);
    const dragStartHex = useRef<{q: number, r: number} | null>(null);
    const isDraggingUnit = useRef(false);

    const isPanning = useRef(false);
    const isPainting = useRef(false); // New: Track if painting
    const lastPaintHex = useRef<string>(""); // Prevent spamming same tile

    const pointerDownStart = useRef<{x: number, y: number} | null>(null);
    const pendingAction = useRef<boolean>(false); 

    // Touch specific state
    const lastPinchDist = useRef<number>(0);
    const lastTouchPos = useRef<{x: number, y: number} | null>(null);

    // Track hovered hex for visual feedback
    const hoveredHexRef = useRef<Hex | null>(null);

    // Track selected agent for the render loop
    const selectedAgentRef = useRef<Agent | null>(selectedAgent);
    useEffect(() => {
        selectedAgentRef.current = selectedAgent;
    }, [selectedAgent]);

    // --- Camera Control Logic ---
    const centerCamera = () => {
        if (!canvasRef.current || !wrapperRef.current) return;

        // Ensure dims are fresh
        canvasRef.current.width = wrapperRef.current.clientWidth;
        canvasRef.current.height = wrapperRef.current.clientHeight;

        const cw = engine.mapConfig.w;
        const ch = engine.mapConfig.h;

        // Calculate grid visual center
        const centerHex = { q: Math.floor(cw / 2), r: Math.floor(ch / 2) };
        const p = HexUtils.toPx(centerHex.q, centerHex.r, engine.mapConfig);

        // Visual adjustments
        const verticalOffset = -BLOCK_HEIGHT * 2; 

        // Center Point Formula: WorldPos - (ScreenSize / Zoom) / 2
        camera.current.x = p.x - (canvasRef.current.width / camera.current.zoom) / 2;
        camera.current.y = p.y + verticalOffset - (canvasRef.current.height / camera.current.zoom) / 2;
    };

    // Auto-Center Triggers
    useEffect(() => {
        if (isShowcaseMode || transitionPhase === 'IN') {
            const t = setTimeout(centerCamera, 350);
            return () => clearTimeout(t);
        } else if (!isShowcaseMode && transitionPhase === 'IDLE') {
             const t = setTimeout(centerCamera, 350);
             return () => clearTimeout(t);
        }
    }, [isShowcaseMode, transitionPhase, engine.mapConfig.w, engine.mapConfig.h]);

    // Resize Observer for Fluid Layout
    useEffect(() => {
        if (!wrapperRef.current || !canvasRef.current) return;

        const resizeObserver = new ResizeObserver(() => {
            if (wrapperRef.current && canvasRef.current) {
                canvasRef.current.width = wrapperRef.current.clientWidth;
                canvasRef.current.height = wrapperRef.current.clientHeight;

                if (engine.agents.length === 0) {
                    centerCamera();
                }
                drawCurrentFrameRef.current();
            }
        });

        resizeObserver.observe(wrapperRef.current);
        centerCamera();

        return () => resizeObserver.disconnect();
    }, [engine]);

    // Render Loop
    useEffect(() => {
        let frameId: number;
        let lastTime = 0;
        let acc = 0;
        const targetFPS = 60;
        const step = 1000 / targetFPS;
        let frameCount = 0;
        let lastFpsTime = 0;

        const drawFrame = () => {
            const ctx = canvasRef.current?.getContext('2d');
            if (ctx) {
                const highlight = draggedAgentRef.current || selectedAgentRef.current || null;
                rendererRef.current.draw(ctx, engine, camera.current, highlight, fpsRef.current, hoveredHexRef.current, hoveredSkill); 
            }
        };

        drawCurrentFrameRef.current = drawFrame;

        const loop = (t: number) => {
            if (!lastTime) lastTime = t;
            const dt = t - lastTime;
            lastTime = t;

            frameCount++;
            if (t - lastFpsTime >= 1000) {
                fpsRef.current = frameCount;
                frameCount = 0;
                lastFpsTime = t;
            }

            if (engine.isRunning) {
                acc += dt;
                if (acc > 200) acc = 200;

                const frameEvents: GameEvent[] = [];
                while (acc >= step) {
                    const sdt = (step / 1000) * engine.timeScale;
                    engine.tick(sdt);
                    engine.battleTime += sdt;
                    acc -= step;
                    frameEvents.push(...engine.events);
                }

                if (frameEvents.length > 0) {
                    rendererRef.current.processEventsWithEngine(frameEvents, engine);
                }
            }

            rendererRef.current.update(dt / 1000, engine);

            if (transitionPhase !== 'IDLE') {
                const elapsed = (performance.now() - transitionStartTime.current) / 1000;
                const progress = Math.min(1.0, elapsed / 1.2);
                rendererRef.current.setTransition(progress, transitionPhase);
            } else {
                rendererRef.current.setTransition(0, 'IDLE');
            }

            drawFrame();
            frameId = requestAnimationFrame(loop);
        };

        engine.onWin = (team) => {
            onWin(team);
        };

        frameId = requestAnimationFrame(loop);
        return () => cancelAnimationFrame(frameId);
    }, [engine, onWin, hoveredSkill, transitionPhase]);

    // Input Handling
    useEffect(() => {
        const cvs = canvasRef.current;
        if (!cvs) return;

        const getScreenCoords = (x: number, y: number) => {
            const rect = cvs.getBoundingClientRect();
            return {
                x: x - rect.left,
                y: y - rect.top
            };
        };

        const getHexFromCoords = (sx: number, sy: number) => {
            const hex = rendererRef.current.getHexAtScreenPoint(sx, sy, camera.current, engine);
            if (hex) return hex;

            return HexUtils.fromPx(
                sx / camera.current.zoom + camera.current.x,
                sy / camera.current.zoom + camera.current.y,
                engine.mapConfig
            );
        };

        const getHitAgentFromCoords = (sx: number, sy: number) => {
            const wx = sx / camera.current.zoom + camera.current.x;
            const wy = sy / camera.current.zoom + camera.current.y;
            const sorted = [...engine.agents].sort((a, b) => b.py - a.py);

            for (const agent of sorted) {
                if (agent.hp <= 0 && agent.fullyDead) continue;
                const h = rendererRef.current.getTerrainHeight(agent.q, agent.r, engine);
                const baseX = agent.px;
                const baseY = agent.py - h;
                const dx = Math.abs(wx - baseX);
                const dy = wy - (baseY - 40); 
                if (dx < 30 && Math.abs(dy) < 50) return agent;
            }
            return null;
        };

        const getWorldPosFromCoords = (sx: number, sy: number) => {
            const wx = sx / camera.current.zoom + camera.current.x;
            const hex = rendererRef.current.getHexAtScreenPoint(sx, sy, camera.current, engine);
            let h = BLOCK_HEIGHT + 6;
            if (hex) h = rendererRef.current.getTerrainHeight(hex.q, hex.r, engine);
            const wy = sy / camera.current.zoom + camera.current.y + h;
            return { x: wx, y: wy };
        };

        const handleActionAt = (h: Hex) => {
            if (engine.isRunning || winner !== null) return;
            const k = HexUtils.key(h);
            if (lastPaintHex.current === k) return; 

            lastPaintHex.current = k;
            if (tool === ToolType.ADD_BLUE) engine.addAgent(Team.BLUE, h.q, h.r, hpInput);
            else if (tool === ToolType.ADD_RED) engine.addAgent(Team.RED, h.q, h.r, hpInput);
            else if (tool === ToolType.OBSTACLE) {
                if (engine.getAgentAt(h.q, h.r)) engine.removeAgent(h.q, h.r);
                engine.setObstacle(h.q, h.r, selectedObstacle);
            }
            else if (tool === ToolType.DELETE) {
                if (engine.hasObstacle(h.q, h.r)) engine.removeObstacle(h.q, h.r);
                if (engine.getAgentAt(h.q, h.r)) {
                    engine.removeAgent(h.q, h.r);
                    onSelect(null);
                }
            }
        };

        // SHARED DOWN
        const handleDown = (sx: number, sy: number, button: number = 0) => {
            pointerDownStart.current = { x: sx, y: sy };

            if (button === 2) {
                isPanning.current = true;
                pendingAction.current = false;
                return;
            }

            const hitAgent = getHitAgentFromCoords(sx, sy);
            if (hitAgent && tool === ToolType.SELECT) {
                pendingAction.current = false;
                onSelect(hitAgent);
                if (!engine.isRunning) {
                    draggedAgentRef.current = hitAgent;
                    dragStartHex.current = { q: hitAgent.q, r: hitAgent.r };
                    isDraggingUnit.current = true;
                }
                return;
            }

            const h = getHexFromCoords(sx, sy);
            const gridAgent = engine.getAgentAt(h.q, h.r);
            if (gridAgent && tool === ToolType.SELECT && !hitAgent) {
                 pendingAction.current = false;
                 onSelect(gridAgent);
                 if (!engine.isRunning) {
                    draggedAgentRef.current = gridAgent;
                    dragStartHex.current = { q: gridAgent.q, r: gridAgent.r };
                    isDraggingUnit.current = true;
                 }
                 return;
            }

            pendingAction.current = true;
            isPanning.current = false;

            if (!engine.isRunning && tool !== ToolType.SELECT) {
                isPainting.current = true;
                lastPaintHex.current = ""; 
                if (engine.isValid(h.q, h.r)) {
                    handleActionAt(h);
                }
            }
        };

        // SHARED MOVE
        const handleMove = (sx: number, sy: number, dx: number, dy: number) => {
            const h = getHexFromCoords(sx, sy);
            hoveredHexRef.current = engine.isValid(h.q, h.r) ? h : null;

            if (tool === ToolType.SELECT && !isDraggingUnit.current && !isPanning.current) {
                const hit = getHitAgentFromCoords(sx, sy);
                if (cvs) cvs.style.cursor = hit ? 'pointer' : 'default';
            } else if (isDraggingUnit.current && cvs) {
                cvs.style.cursor = 'grabbing';
            }

            if (isPanning.current) {
                camera.current.x -= dx / camera.current.zoom;
                camera.current.y -= dy / camera.current.zoom;
                return;
            }

            if (isDraggingUnit.current && draggedAgentRef.current) {
                const wPos = getWorldPosFromCoords(sx, sy);
                draggedAgentRef.current.px = wPos.x;
                draggedAgentRef.current.py = wPos.y;
                return;
            }

            if (isPainting.current && !engine.isRunning) {
                if (engine.isValid(h.q, h.r)) {
                    handleActionAt(h);
                }
            }

            if (pendingAction.current && pointerDownStart.current && !isPainting.current) {
                const dist = Math.sqrt((sx - pointerDownStart.current.x)**2 + (sy - pointerDownStart.current.y)**2);
                if (dist > 5) {
                    pendingAction.current = false;
                    isPanning.current = true;
                    camera.current.x -= dx / camera.current.zoom;
                    camera.current.y -= dy / camera.current.zoom;
                }
            }
        };

        // SHARED UP
        const handleUp = (sx: number, sy: number) => {
            isPainting.current = false;
            lastPaintHex.current = "";

            if (isPanning.current) {
                isPanning.current = false;
                pointerDownStart.current = null;
                return;
            }

            if (isDraggingUnit.current && draggedAgentRef.current) {
                const h = getHexFromCoords(sx, sy);
                const agent = draggedAgentRef.current;
                const isValidHex = engine.isValid(h.q, h.r);
                const isObstacle = engine.obstacles.has(HexUtils.key(h));
                const occupant = engine.getAgentAt(h.q, h.r);
                const isOccupiedByOther = occupant && occupant !== agent;

                if (isValidHex && !isObstacle && !isOccupiedByOther) {
                    engine.updateAgentPosition(agent, h.q, h.r);
                    const p = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                    agent.px = p.x; agent.py = p.y;
                } else {
                    if (dragStartHex.current) {
                        agent.q = dragStartHex.current.q;
                        agent.r = dragStartHex.current.r;
                        const p = HexUtils.toPx(agent.q, agent.r, engine.mapConfig);
                        agent.px = p.x; agent.py = p.y;
                        engine.updateAgentPosition(agent, agent.q, agent.r);
                    }
                }

                draggedAgentRef.current = null;
                dragStartHex.current = null;
                isDraggingUnit.current = false;
                onSelect(agent);
                if (cvs) cvs.style.cursor = 'default';
                return;
            }

            if (pendingAction.current) {
                pendingAction.current = false;
                if (tool === ToolType.SELECT) {
                    const hitAgent = getHitAgentFromCoords(sx, sy);
                    if (hitAgent) onSelect(hitAgent);
                    else onSelect(null);
                } 
            }
            pointerDownStart.current = null;
        };

        // Mouse Listeners
        const handleMouseDown = (e: MouseEvent) => {
            const pos = getScreenCoords(e.clientX, e.clientY);
            handleDown(pos.x, pos.y, e.button);
        };
        const handleMouseMove = (e: MouseEvent) => {
            const pos = getScreenCoords(e.clientX, e.clientY);
            handleMove(pos.x, pos.y, e.movementX, e.movementY);
        };
        const handleMouseUp = (e: MouseEvent) => {
            const pos = getScreenCoords(e.clientX, e.clientY);
            handleUp(pos.x, pos.y);
        };

        // Touch Listeners
        const onTouchStart = (e: TouchEvent) => {
            e.preventDefault();
            if (e.touches.length === 1) {
                const pos = getScreenCoords(e.touches[0].clientX, e.touches[0].clientY);
                lastTouchPos.current = pos;
                handleDown(pos.x, pos.y, 0);
            } else if (e.touches.length === 2) {
                const t1 = getScreenCoords(e.touches[0].clientX, e.touches[0].clientY);
                const t2 = getScreenCoords(e.touches[1].clientX, e.touches[1].clientY);
                lastPinchDist.current = Math.hypot(t1.x - t2.x, t1.y - t2.y);
                // When 2 fingers down, cancel single finger drag/selection
                pendingAction.current = false;
                isDraggingUnit.current = false;
                draggedAgentRef.current = null;
            }
        };

        const onTouchMove = (e: TouchEvent) => {
            e.preventDefault();
            if (e.touches.length === 1 && lastTouchPos.current) {
                const pos = getScreenCoords(e.touches[0].clientX, e.touches[0].clientY);
                const dx = pos.x - lastTouchPos.current.x;
                const dy = pos.y - lastTouchPos.current.y;
                handleMove(pos.x, pos.y, dx, dy);
                lastTouchPos.current = pos;
            } else if (e.touches.length === 2) {
                const t1 = getScreenCoords(e.touches[0].clientX, e.touches[0].clientY);
                const t2 = getScreenCoords(e.touches[1].clientX, e.touches[1].clientY);
                const currentDist = Math.hypot(t1.x - t2.x, t1.y - t2.y);

                if (lastPinchDist.current > 0) {
                    const delta = currentDist - lastPinchDist.current;
                    const zoomSensitivity = 0.005;
                    camera.current.zoom = Math.max(0.5, Math.min(3.0, camera.current.zoom + delta * zoomSensitivity));
                }
                lastPinchDist.current = currentDist;
            }
        };

        const onTouchEnd = (e: TouchEvent) => {
            e.preventDefault();
            if (e.changedTouches.length > 0 && lastTouchPos.current) {
                const pos = getScreenCoords(e.changedTouches[0].clientX, e.changedTouches[0].clientY);
                handleUp(pos.x, pos.y);
            }
            lastTouchPos.current = null;
            lastPinchDist.current = 0;
        };

        const handleWheel = (e: WheelEvent) => {
            e.preventDefault();
            const delta = e.deltaY > 0 ? -0.1 : 0.1;
            camera.current.zoom = Math.max(0.5, Math.min(3.0, camera.current.zoom + delta));
        };

        const handleContextMenu = (e: MouseEvent) => e.preventDefault();

        cvs.addEventListener('mousedown', handleMouseDown);
        window.addEventListener('mousemove', handleMouseMove);
        window.addEventListener('mouseup', handleMouseUp);
        cvs.addEventListener('wheel', handleWheel, { passive: false });
        cvs.addEventListener('contextmenu', handleContextMenu);

        // Mobile touch events
        cvs.addEventListener('touchstart', onTouchStart, { passive: false });
        cvs.addEventListener('touchmove', onTouchMove, { passive: false });
        cvs.addEventListener('touchend', onTouchEnd, { passive: false });

        return () => {
            cvs.removeEventListener('mousedown', handleMouseDown);
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseup', handleMouseUp);
            cvs.removeEventListener('wheel', handleWheel);
            cvs.removeEventListener('contextmenu', handleContextMenu);
            cvs.removeEventListener('touchstart', onTouchStart);
            cvs.removeEventListener('touchmove', onTouchMove);
            cvs.removeEventListener('touchend', onTouchEnd);
        };
    }, [engine, tool, selectedObstacle, hpInput, onSelect, winner]);

    return (
        <div ref={wrapperRef} className="flex-1 overflow-hidden relative bg-slate-950 border-r border-slate-700">
            <canvas 
                ref={canvasRef} 
                className={`block shadow-inner ${tool === ToolType.SELECT ? 'cursor-default' : 'cursor-crosshair'}`}
                style={{ backgroundColor: engine.currentScene.background }} 
            />

            {/* STANDARD MODE VICTORY SCREEN */}
            {winner !== null && !isShowcaseMode && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/70 z-50">
                    <div className="text-center p-8 bg-slate-900 rounded-lg border border-slate-700 shadow-2xl animate-bounce-in">
                        <h2 className={`text-4xl font-bold mb-4 font-serif tracking-widest ${winner === Team.BLUE ? 'text-blue-400' : 'text-red-400'}`}>
                            {winner === Team.BLUE ? 'VICTORY' : 'DEFEAT'}
                        </h2>
                        <button onClick={rematch} className="bg-slate-700 hover:bg-slate-600 text-white font-bold py-2 px-6 rounded border border-slate-500">REMATCH</button>
                    </div>
                </div>
            )}
        </div>
    );
};

