import { AISystem } from "./systems/ai";
import { AgentManager } from "./systems/agentManager";

export type SpecialVisualStatus = 'NONE' | 'FROZEN' | 'POLYMORPH' | 'STASIS';

export class Agent {
    public id: string;
    public team: Team;
    public role: Role;
    public q: number;
    public r: number;
    public px: number;
    public py: number;

    // Stats
    public hp: number = 100;
    public maxHp: number = 100;
    public mp: number = 0;
    public maxMp: number = 100;
    public moveSpeed: number = 1.0; 
    public moveSpeedMult: number = 1.0; 
    public jump: number = 1; // Vertical mobility tier
    public weight: number = 1; // Knockback resistance
    public movementType: MovementType = MovementType.GROUND;

    // Skills
    public skillIds: (string | null)[] = [null, null, null];
    public skills: (Skill | null)[] = [];
    public castingSkillIdx: number = -1;
    public castTimer: number = 0;
    public castingAnimationTimer: number = 0; 
    public curCDs: number[] = [0, 0, 0];

    // State / AI
    public isMoving: boolean = false;
    public path: Hex[] = []; 
    public trajectory: Hex[] = []; 
    public moveProgress: number = 0;
    public facing: number = 1; 
    public target: Agent | null = null;
    public targetHex: Hex | null = null; 
    public btStatus: string = "待機";
    public bt: BTNode | null = null;

    // Status Effects (Managed by StatusSystem)
    public stunTimer: number = 0;
    public banishTimer: number = 0;
    public silenceTimer: number = 0;
    public banished: boolean = false;
    public dotTimer: number = 0;
    public dotDmg: number = 0;
    public hotTimer: number = 0;
    public hotVal: number = 0;

    // Visual State
    public visualStatus: SpecialVisualStatus = 'NONE';
    public spawnTimer: number = 0;

    // Lifecycle
    public deadLogged: boolean = false;
    public fullyDead: boolean = false;
    public animState: AnimState = AnimState.IDLE;
    public animTimer: number = 0; 
    public hitFlashTimer: number = 0;

    // Physics (Enhanced for 3D bounce)
    public physics = { 
        x: 0, y: 0, z: 0,          
        vx: 0, vy: 0, vz: 0,       
        angle: 0, vAngle: 0   
    };

    public initialState: { q: number, r: number, maxHp: number, skillIds: (string|null)[], role: Role };

    constructor(team: Team, q: number, r: number, config: MapConfig) {
        this.id = Math.random().toString(36).substr(2, 5).toUpperCase();
        this.team = team;
        this.role = Role.WARRIOR; 
        this.q = q;
        this.r = r;

        const p = HexUtils.toPx(q, r, config);
        this.px = p.x;
        this.py = p.y;
        this.facing = team === Team.BLUE ? 1 : -1;

        this.initialState = { q, r, maxHp: 100, skillIds: [], role: Role.WARRIOR };
    }

    setAnim(state: AnimState) {
        if (this.animState !== state && this.animState !== AnimState.DEAD) {
            this.animState = state;
            this.animTimer = 0;
        }
    }

    saveState() {
        this.initialState = {
            q: this.q,
            r: this.r,
            maxHp: this.maxHp,
            skillIds: [...this.skillIds],
            role: this.role
        };
    }

    reset(config: MapConfig) {
        this.q = this.initialState.q;
        this.r = this.initialState.r;
        const p = HexUtils.toPx(this.q, this.r, config);
        this.px = p.x;
        this.py = p.y;

        this.maxHp = this.initialState.maxHp;
        this.hp = this.maxHp;
        this.mp = 0;

        this.skillIds = [...this.initialState.skillIds];
        this.role = this.initialState.role;

        const stats = UNIT_DB[this.role];
        if (stats) {
            this.moveSpeed = stats.moveSpeed;
            this.maxMp = stats.maxMp;
            this.jump = stats.jump;
            this.weight = stats.weight;
            this.movementType = stats.movementType;
        }

        this.castingSkillIdx = -1;
        this.castTimer = 0;
        this.castingAnimationTimer = 0;
        this.curCDs = [0, 0, 0];

        this.isMoving = false;
        this.moveSpeedMult = 1.0; 
        this.path = [];
        this.moveProgress = 0;

        this.stunTimer = 0;
        this.banishTimer = 0;
        this.silenceTimer = 0;
        this.banished = false;
        this.dotTimer = 0;
        this.hotTimer = 0;
        this.visualStatus = 'NONE';

        this.hitFlashTimer = 0;
        this.deadLogged = false;
        this.fullyDead = false;
        this.animState = AnimState.IDLE;
        this.spawnTimer = 0.5; 

        this.target = null;
        this.targetHex = null;
        this.physics = { x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0, angle: 0, vAngle: 0 };
    }
}

export class GameEngine {
    public agents: Agent[] = [];

    // Delegated to MapSystem
    get mapKeys() { return this.map.mapKeys; }
    get obstacles() { return this.map.obstacles; }

    // Delegated to CombatSystem (Single Source of Truth)
    get projectiles() { return this.combat.projectiles; }

    public events: GameEvent[] = [];

    public isRunning: boolean = false;
    public timeScale: number = 1.0;
    public battleTime: number = 0;
    public mapVersion: number = 0; 

    public mapConfig: MapConfig = { w: 12, h: 8, offsetX: 0, offsetY: 0 };
    public currentScene: SceneTheme = SCENE_DB[0];

    public logs: LogEntry[] = [];
    public skillDB: Skill[] = [...DEFAULT_SKILL_DB];

    public onWin?: (team: Team) => void;

    // AI Director State
    public directorTargetId: string | null = null;
    private directorTimer: number = 0;

    public agentMap: Map<number, Agent> = new Map();

    // Subsystems
    public movement: MovementSystem;
    public status: StatusSystem;
    public combat: CombatSystem;
    public map: MapSystem;
    public ai: AISystem;
    public agentManager: AgentManager;

    constructor() {
        this.movement = new MovementSystem();
        this.status = new StatusSystem();
        this.combat = new CombatSystem();
        this.map = new MapSystem();
        this.ai = new AISystem();
        this.agentManager = new AgentManager();

        this.map.randomizeEnvironment(this);
    }

    // --- Passthroughs ---

    addAgent(team: Team, q: number, r: number, hpOverride?: number) { return this.agentManager.addAgent(this, team, q, r, hpOverride); }

    // Updated to support Paint Mode
    setObstacle(q: number, r: number, type: string) { this.map.setObstacle(q, r, type); }
    removeObstacle(q: number, r: number) { this.map.removeObstacle(q, r); }
    toggleObstacle(q: number, r: number, type: string = 'WALL') { this.map.toggleObstacle(q, r, this, type); }

    isValid(q: number, r: number) { return this.map.isValid(q, r); }
    // Updated to support flying logic check
    isBlocked(q: number, r: number, ignoreId?: string, movementType: MovementType = MovementType.GROUND) { return this.map.isBlocked(q, r, this, ignoreId, movementType); }
    isValidHash(h: number) { return this.map.isValidHash(h); }
    hasObstacle(q: number, r: number) { return this.map.hasObstacle(q, r); }
    hasObstacleHash(h: number) { return this.map.hasObstacleHash(h); }
    randomizeEnvironment() { this.map.randomizeEnvironment(this); }
    rebuildMap() { this.map.rebuildMap(this); }

    removeAgent(q: number, r: number) {
        const hash = HexUtils.hash(q, r);
        const agent = this.agentMap.get(hash);
        if (agent) {
            this.agents = this.agents.filter(a => a !== agent);
            this.agentMap.delete(hash);
        }
    }

    getAgentAt(q: number, r: number): Agent | undefined {
        const agent = this.agentMap.get(HexUtils.hash(q, r));
        return (agent && agent.hp > 0) ? agent : undefined;
    }

    updateAgentPosition(agent: Agent, newQ: number, newR: number) {
        this.agentMap.delete(HexUtils.hash(agent.q, agent.r));
        agent.q = newQ;
        agent.r = newR;
        this.agentMap.set(HexUtils.hash(agent.q, agent.r), agent);
    }

    // --- Core Logic Control ---

    play() {
        if (!this.isRunning) {
            this.agents.forEach(a => a.saveState());
            this.battleTime = 0;
            this.logs = [];
            this.log(null, '開始', null, '戰鬥分析開始');
        }

        this.agentMap.clear();

        this.agents.forEach(a => {
            a.skills = a.skillIds.map(id => {
                if (!id) return null;
                return this.skillDB.find(s => s.id === id) || null;
            });
            a.bt = this.ai.buildAI(a, this); // Use AI System
            a.animState = AnimState.IDLE;
            if (a.hp > 0) {
                this.agentMap.set(HexUtils.hash(a.q, a.r), a);
            }
        });
        this.isRunning = true;
    }

    stop() { this.isRunning = false; }

    restart() {
        this.stop();
        this.agentMap.clear();
        this.agents.forEach(a => {
            a.reset(this.mapConfig);
            this.agentMap.set(HexUtils.hash(a.q, a.r), a);
        });
        this.combat.projectiles = []; // Clear projectiles via combat system
        this.battleTime = 0;
        this.play();
    }

    clear(keepScene: boolean = false) {
        this.stop();
        this.agents = [];
        this.agentMap.clear();
        this.map.obstacles.clear();
        this.map.obstaclesHash.clear();
        this.combat.projectiles = []; // Clear projectiles via combat system
        this.logs = [];
        this.directorTargetId = null;
        if (!keepScene) this.map.randomizeEnvironment(this); 
        else this.map.rebuildMap(this); 
    }

    // --- Main Game Loop ---

    tick(dt: number) {
        if (!this.isRunning) return;

        // Memory Optimization: Reuse array instead of reallocation
        this.events.length = 0;

        this.updateDirector(dt); // AI Director Logic

        // Win Condition Check
        let blue = 0, red = 0;
        for (const a of this.agents) {
            if (a.hp > 0) a.team === Team.BLUE ? blue++ : red++;
        }
        if (blue === 0 && red > 0) { this.stop(); this.onWin?.(Team.RED); }
        else if (red === 0 && blue > 0) { this.stop(); this.onWin?.(Team.BLUE); }

        for (const a of this.agents) {
            if (a.hitFlashTimer > 0) a.hitFlashTimer -= dt;

            // Physics delegated to MovementSystem
            this.movement.updatePhysics(a, dt, this);

            if (a.hp <= 0) {
                this.agentManager.handleDeadState(a, this);
                continue;
            }

            // --- DELEGATED SYSTEMS ---
            this.status.update(a, dt, this);

            // Movement Update
            if (a.isMoving && a.path.length > 0 && a.stunTimer <= 0) {
                this.movement.updateMovement(a, dt, this);
            }

            // AI Update
            if (a.bt) {
                const resetTree = (node: BTNode) => { 
                    node.status = null; 
                    if (node.c) node.c.forEach(resetTree); 
                };
                resetTree(a.bt);
                a.bt.tick(a);
            }
        }

        this.combat.update(dt, this);
        this.movement.resolveStacking(this);
    }

    // --- Loop Sub-Methods ---

    private updateDirector(dt: number) {
        this.directorTimer -= dt;

        // Ensure current target is still valid
        const current = this.agents.find(a => a.id === this.directorTargetId);
        if (!current || current.hp <= 0) {
            this.directorTimer = -1; // Force switch
        }

        if (this.directorTimer <= 0) {
            // Pick new target logic (simplified for brevity, logic remains same)
            const alive = this.agents.filter(a => a.hp > 0);
            if (alive.length > 0) {
                const ultCasters = alive.filter(a => a.castingSkillIdx !== -1 && a.skills[a.castingSkillIdx]?.tag === 'ULT');
                if (ultCasters.length > 0) {
                     this.directorTargetId = ultCasters[Math.floor(Math.random() * ultCasters.length)].id;
                     this.directorTimer = 4.0;
                     return;
                }

                this.directorTargetId = alive[Math.floor(Math.random() * alive.length)].id;
                this.directorTimer = 3.0;
            }
        }
    }

    performCast(a: Agent, i: number): NodeState {
        if (a.castingSkillIdx === -1) {
            a.castingSkillIdx = i;
            a.castTimer = a.skills[i]!.cast;
            a.castingAnimationTimer = a.skills[i]!.cast; 

            a.btStatus = `詠唱 ${a.skills[i]!.tag}`;

            let targetName = '地面';
            if (a.target) targetName = a.target.id;
            else if (a.targetHex) targetName = `(${a.targetHex.q},${a.targetHex.r})`;

            this.log(a, '詠唱', targetName, a.skills[i]!.name);
            this.events.push({ type: 'CAST_START', pos: {x: a.px, y: a.py}, sourceId: a.id, skill: a.skills[i]! });

            a.setAnim(AnimState.ATTACK);

            if (a.target) {
                a.facing = a.target.px > a.px ? 1 : -1;
            } else if (a.targetHex) {
                const tx = HexUtils.toPx(a.targetHex.q, a.targetHex.r, this.mapConfig).x;
                a.facing = tx > a.px ? 1 : -1;
            }
        }
        return NodeState.RUNNING;
    }

    log(agent: Agent | null, action: string, targetId: string | null, detail: string) {
        const time = this.battleTime.toFixed(1);
        const entry: LogEntry = {
            id: Math.random().toString(36),
            time,
            action,
            target: targetId || '自身',
            detail,
            agentId: agent?.id || (agent === null ? '系統' : undefined),
            team: agent?.team,
            loc: agent ? `@(${agent.q},${agent.r})` : undefined
        };
        this.logs.push(entry);
        if (this.logs.length > 2000) this.logs.shift();
    }
}

import { GameEngine } from "../game";
import { SCENE_DB } from "../../data/scenes";
import { HexUtils } from "../utils";
import { BLOCK_HEIGHT, MAX_TERRAIN_TIER } from "../../constants";
import { MovementType } from "../../types";
import { OBSTACLE_DB } from "../../data/obstacles";

export class MapSystem {
    public mapKeys: Set<string> = new Set();
    private validHashes: Set<number> = new Set();

    // Changed from Set to Map to store Obstacle Type ID (e.g. 'WALL', 'TREE')
    public obstacles: Map<string, string> = new Map();
    public obstaclesHash: Set<number> = new Set();

    // Terrain Source of Truth (Generated once per rebuild)
    private _heightMap: Map<string, number> = new Map();

    constructor() {}

    public getTerrainHeight(q: number, r: number): number {
        // Direct lookup from generated map (returns 0 if void/out of bounds)
        return this._heightMap.get(HexUtils.key({q, r})) || 0;
    }

    public randomizeEnvironment(engine: GameEngine) {
        engine.mapConfig.w = Math.floor(10 + Math.random() * 4); // Slightly wider maps for amphitheater
        engine.mapConfig.h = Math.floor(8 + Math.random() * 4);
        engine.currentScene = SCENE_DB[Math.floor(Math.random() * SCENE_DB.length)];
        this.rebuildMap(engine);
    }

    public rebuildMap(engine: GameEngine) {
        this.mapKeys.clear();
        this.validHashes.clear();
        this.obstacles.clear();
        this.obstaclesHash.clear();
        this._heightMap.clear();

        const W = engine.mapConfig.w;
        const H = engine.mapConfig.h;
        const tempHeights = new Map<string, number>();

        // =====================================================================
        // PHASE 1: Raw Generation (Amphitheater Gradient)
        // =====================================================================
        for (let q = 0; q < W; q++) {
            for (let r = 0; r < H; r++) {
                const hex = HexUtils.offsetToAxial(q, r, engine.mapConfig);
                const k = HexUtils.key(hex);

                this.mapKeys.add(k);
                this.validHashes.add(HexUtils.hash(hex.q, hex.r));

                // View Factor: 
                // r is the 'row'. In this offset grid, higher r = lower on screen (Front).
                // We want High Ground at the Back (Low r), Low Ground at Front (High r).
                const depthProgress = r / H; // 0.0 (Back) -> 1.0 (Front)
                const viewFactor = 1.0 - depthProgress; 

                // Noise Base (0.0 to 1.0)
                const noise = Math.random();

                // Height Logic: 
                // Back: Allow full height (e.g. up to Tier 4 or 5)
                // Front: Cap strictly to Tier 0 or 1 to prevent occlusion
                // Formula: BaseNoise * (MinBias + ViewFactor * Scale)

                let rawHeight = 0;

                if (depthProgress > 0.7) {
                    // Front 30%: Very flat, mostly Tier 0, rare Tier 1
                    rawHeight = noise * 0.8; 
                } else {
                    // Back/Mid: Tier 0 to Tier 4
                    // Bias towards 1.0 base, plus ViewFactor bonus
                    rawHeight = noise * (1.5 + viewFactor * 3.5);
                }

                tempHeights.set(k, rawHeight);
            }
        }

        // =====================================================================
        // PHASE 2: Smoothing (Blur Pass)
        // =====================================================================
        // This removes "Islands" and creates rolling slopes
        const smoothedHeights = new Map<string, number>();

        tempHeights.forEach((h, key) => {
            const [q, r] = key.split(',').map(Number);
            const neighbors = HexUtils.neighbors({q, r});

            let sum = h;
            let count = 1;

            // Weight self higher to retain some randomness
            sum += h; 
            count++;

            neighbors.forEach(n => {
                const nk = HexUtils.key(n);
                if (tempHeights.has(nk)) {
                    sum += tempHeights.get(nk)!;
                    count++;
                }
            });

            smoothedHeights.set(key, sum / count);
        });

        // =====================================================================
        // PHASE 3: Quantize & Store
        // =====================================================================
        smoothedHeights.forEach((raw, key) => {
            let tier = Math.floor(raw);
            // Clamp
            tier = Math.max(0, Math.min(MAX_TERRAIN_TIER, tier));
            this._heightMap.set(key, tier * BLOCK_HEIGHT);
        });

        // 2. Prune Disconnected Islands (Rule: No Disconnected Tiles)
        this.pruneDisconnected(engine);

        // =====================================================================
        // PHASE 4: Auto-Decoration
        // =====================================================================
        this.generateDecorations(engine);

        engine.mapVersion++;
    }

    private generateDecorations(engine: GameEngine) {
        const obstacleType = engine.currentScene.obstacleStyle || 'WALL';

        this._heightMap.forEach((hPx, key) => {
            const [q, r] = key.split(',').map(Number);

            // Skip if unit exists (though usually map is empty on rebuild)
            if (engine.getAgentAt(q, r)) return;

            const myTier = hPx / BLOCK_HEIGHT;
            const hex = {q, r};

            // Analyze Neighbors
            const neighbors = HexUtils.neighbors(hex);
            let isCliffBottom = false;
            let isFlatHigh = true;
            let validNeighbors = 0;

            neighbors.forEach(n => {
                if (!this.isValid(n.q, n.r)) return;
                validNeighbors++;

                const nH = this.getTerrainHeight(n.q, n.r);
                const nTier = nH / BLOCK_HEIGHT;

                // If a neighbor is > 1 tier higher, I am at the bottom of a cliff/wall
                // Placing an obstacle here looks like a retaining wall or rocks falling
                if (nTier > myTier + 1) isCliffBottom = true;

                // If any neighbor has different height, I am not flat
                if (Math.abs(nTier - myTier) > 0.5) isFlatHigh = false;
            });

            // Rule 1: Cliff Decor (High Priority)
            // Visually connects the height difference
            if (isCliffBottom) {
                if (Math.random() < 0.7) {
                    this.setObstacle(q, r, obstacleType);
                    return;
                }
            }

            // Rule 2: Edge Noise
            // If on the rim of the map, high chance of obstacles to frame the arena
            if (validNeighbors < 6) {
                if (Math.random() < 0.3) {
                    this.setObstacle(q, r, obstacleType);
                    return;
                }
            }

            // Rule 3: High Ground Forests
            // If I am high (> Tier 2) and flat, grow trees to create strategic cover
            // Forests block movement but fit the theme
            if (myTier >= 2 && isFlatHigh) {
                if (Math.random() < 0.25) {
                    const type = engine.currentScene.textureType === 'FOREST' ? 'TREE' : obstacleType;
                    this.setObstacle(q, r, type);
                }
            }
        });
    }

    private pruneDisconnected(engine: GameEngine) {
        if (this.validHashes.size === 0) return;

        // Find a center-ish tile as the seed
        const centerQ = Math.floor(engine.mapConfig.w / 2);
        const centerR = Math.floor(engine.mapConfig.h / 2);
        const centerHex = HexUtils.offsetToAxial(centerQ, centerR, engine.mapConfig);

        // Find closest valid tile to ideal center
        let seed = HexUtils.hash(centerHex.q, centerHex.r);
        if (!this.validHashes.has(seed)) {
            // Fallback: pick first valid
            seed = this.validHashes.values().next().value;
        }

        // BFS to find all reachable tiles
        const reachable = new Set<number>();
        const queue: number[] = [seed];
        reachable.add(seed);

        // Standard BFS
        let head = 0;
        while(head < queue.length) {
            const currentHash = queue[head++];
            const current = HexUtils.unhash(currentHash);
            // Height Aware? For checking island connectivity, we treat blocks as connected if they exist
            // Vertical movement is a pathfinding problem, not a map validity problem.
            const neighbors = HexUtils.neighbors(current);

            for (const n of neighbors) {
                const nHash = HexUtils.hash(n.q, n.r);
                if (this.validHashes.has(nHash) && !reachable.has(nHash)) {
                    reachable.add(nHash);
                    queue.push(nHash);
                }
            }
        }

        // Remove anything NOT in reachable set
        const toRemove: number[] = [];
        this.validHashes.forEach(h => {
            if (!reachable.has(h)) toRemove.push(h);
        });

        toRemove.forEach(h => {
            this.validHashes.delete(h);
            const hex = HexUtils.unhash(h);
            const k = HexUtils.key(hex);
            this.mapKeys.delete(k);
            this._heightMap.delete(k); // Clean up height map
        });
    }

    // New: Explicit Set for Painting
    public setObstacle(q: number, r: number, type: string) {
        if (!this.isValid(q, r)) return;
        const k = HexUtils.key({q, r});
        const h = HexUtils.hash(q, r);

        this.obstacles.set(k, type);
        this.obstaclesHash.add(h);
    }

    // New: Explicit Remove for Painting
    public removeObstacle(q: number, r: number) {
        const k = HexUtils.key({q, r});
        const h = HexUtils.hash(q, r);

        this.obstacles.delete(k);
        this.obstaclesHash.delete(h);
    }

    public toggleObstacle(q: number, r: number, engine: GameEngine, type: string = 'WALL') {
        if (!this.isValid(q, r)) return;

        const k = HexUtils.key({q, r});
        const h = HexUtils.hash(q, r);

        if (this.obstaclesHash.has(h)) {
            this.obstacles.delete(k);
            this.obstaclesHash.delete(h);
        } else {
            if (!engine.getAgentAt(q, r)) {
                this.obstacles.set(k, type);
                this.obstaclesHash.add(h);
            }
        }
    }

    public isValid(q: number, r: number) { 
        return this.validHashes.has(HexUtils.hash(q, r));
    }

    public isValidHash(h: number) {
        return this.validHashes.has(h);
    }

    public hasObstacle(q: number, r: number) {
        return this.obstaclesHash.has(HexUtils.hash(q, r));
    }

    public hasObstacleHash(h: number) {
        return this.obstaclesHash.has(h);
    }

    // Updated isBlocked to support Flying Logic
    public isBlocked(q: number, r: number, engine: GameEngine, ignoreId: string | null = null, movementType: MovementType = MovementType.GROUND) { 
        const h = HexUtils.hash(q, r);

        // 1. Obstacle Check
        if (this.obstaclesHash.has(h)) {
            const obsId = this.obstacles.get(HexUtils.key({q, r}));
            if (obsId) {
                const def = OBSTACLE_DB[obsId];
                if (def) {
                    if (movementType === MovementType.FLYING) {
                        if (def.blocksFlying) return true;
                    } else {
                        if (def.blocksMovement) return true;
                    }
                } else {
                    return true; // Unknown obstacle, block safe
                }
            } else {
                return true;
            }
        }

        // 2. Unit Collision Check
        const occupant = engine.agentMap.get(h);
        if (occupant) {
            if (occupant.id === ignoreId) return false;
            if (occupant.hp <= 0 || occupant.banished) return false;
            return true;
        }

        // 3. Reserved Path Check
        return engine.agents.some(a => {
            if (a.id === ignoreId) return false;
            if (!a.isMoving || a.path.length === 0) return false;
            const dest = a.path[0];
            return dest.q === q && dest.r === r;
        });
    }
}

import { Agent, GameEngine } from "../game";
import { HexUtils, Vector, NEIGHBOR_HASH_OFFSETS } from "../utils";
import { AnimState, Hex, NodeState, MovementType } from "../../types";
import { BLOCK_HEIGHT } from "../../constants";
import { OBSTACLE_DB } from "../../data/obstacles";

// Constants extracted from game.ts
const PATHFINDING_MAX_ITERATIONS = 2500; 
const QUEUE_CAPACITY = 4096; 
const STACKING_RESOLUTION_FORCE = 5;

const PHYSICS_STIFFNESS_ALIVE = 150;
const PHYSICS_STIFFNESS_DEAD = 0;
// INCREASED DAMPING: Makes units stop snappier, reducing "floating" feel
const PHYSICS_DAMPING_ALIVE = 25; 
const PHYSICS_DAMPING_DEAD = 1.0; 

const GRAVITY = 2000; 

export class MovementSystem {
    // Pathfinding Memory Buffers (Reused to avoid GC)
    private _pfQueue: Int32Array; 
    private _pfCameFrom: Map<number, number> = new Map();
    private _pfBlockers: Set<number> = new Set();

    // Optimization: Reuse Stacking Map to reduce GC
    private _stackingMap = new Map<number, Agent[]>();

    constructor() {
        this._pfQueue = new Int32Array(QUEUE_CAPACITY);
    }

    // =========================================================================================
    // 🏹 RANGE CALCULATION (High Ground Bonus)
    // =========================================================================================

    public getEffectiveRange(a: Hex, targetQ: number, targetR: number, baseRange: number, engine: GameEngine): number {
        const h1 = engine.map.getTerrainHeight(a.q, a.r);
        const h2 = engine.map.getTerrainHeight(targetQ, targetR);

        // Bonus: +1 Range per Block Height advantage
        // Only applies if attacker is higher. No penalty for low ground (to avoid frustration).
        const deltaH = h1 - h2;
        const heightBonus = Math.max(0, Math.floor(deltaH / BLOCK_HEIGHT));

        return baseRange + heightBonus;
    }

    // =========================================================================================
    // 🏃 MOVEMENT & PHYSICS
    // =========================================================================================

    public updatePhysics(a: Agent, dt: number, engine: GameEngine) {
        const isDead = a.hp <= 0;
        const stiffness = isDead ? PHYSICS_STIFFNESS_DEAD : PHYSICS_STIFFNESS_ALIVE; 

        // If airborne (z > 0), reduce drag to allow projectile motion
        const isAirborne = a.physics.z > 0;
        const damping = (isDead && isAirborne) ? 0.5 : (isDead ? PHYSICS_DAMPING_DEAD : PHYSICS_DAMPING_ALIVE);

        // 1. Spring Forces (Return to 0,0 relative local space)
        const fx = -stiffness * a.physics.x;
        const fy = -stiffness * a.physics.y;
        const fRot = -stiffness * a.physics.angle * 0.1; 

        // 2. Acceleration (Force - Damping)
        const ax = fx - damping * a.physics.vx;
        const ay = fy - damping * a.physics.vy;
        const aRot = fRot - damping * a.physics.vAngle;

        // 3. Integrate Velocity
        a.physics.vx += ax * dt;
        a.physics.vy += ay * dt;
        a.physics.vAngle += aRot * dt;

        // 4. Vertical Dynamics (Gravity vs Flight)
        if (a.movementType === MovementType.FLYING && !isDead) {
            // Flying Unit Logic
            if (a.stunTimer > 0 || a.visualStatus === 'FROZEN' || a.visualStatus === 'POLYMORPH') {
                // CRASH STATE: Apply Gravity immediately
                a.physics.vz -= GRAVITY * dt;
            } else {
                // HOVER STATE: Bob around a target altitude
                // Increased to 90 to visually clear walls (80px)
                const hoverHeight = 90; 
                const hoverFreq = 3;
                const targetZ = hoverHeight + Math.sin(engine.battleTime * hoverFreq) * 10;

                // Soft spring to maintain height
                const dz = targetZ - a.physics.z;
                a.physics.vz += dz * 5 * dt;
                a.physics.vz *= 0.95; // Drag to stop oscillation
            }
        } else {
            // Ground Unit Logic
            if (isDead || isAirborne) {
                a.physics.vz -= GRAVITY * dt;
            }
        }

        // 5. Integrate Position
        a.physics.x += a.physics.vx * dt;
        a.physics.y += a.physics.vy * dt;
        a.physics.z += a.physics.vz * dt;
        a.physics.angle += a.physics.vAngle * dt;

        // 6. Ground Collision (Bounce)
        if (a.physics.z < 0) {
            a.physics.z = 0;
            // Elastic collision with ground loss
            if (Math.abs(a.physics.vz) > 100) {
                a.physics.vz = -a.physics.vz * 0.5; // Bounce back
                a.physics.vx *= 0.6; // Ground friction
                a.physics.vy *= 0.6;
                a.physics.vAngle *= 0.5;
            } else {
                a.physics.vz = 0;
            }
        }

        // 7. World Position Drift (Slide effect for dead units)
        if (!isDead && !a.isMoving) {
            const targetPos = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            const dx = targetPos.x - a.px;
            const dy = targetPos.y - a.py;
            const distSq = dx*dx + dy*dy;

            // Increased snap threshold to stop jitter
            if (distSq > 0.5) {
                const driftSpeed = 12.0 * dt;
                a.px += dx * driftSpeed;
                a.py += dy * driftSpeed;
                if (distSq < 2) {
                    a.px = targetPos.x;
                    a.py = targetPos.y;
                }
            } else {
                a.px = targetPos.x;
                a.py = targetPos.y;
            }
        } else if (isDead) {
            // Apply physics velocity to world position (Flying through air)
            a.px += a.physics.vx * dt * 0.1; 
            a.py += a.physics.vy * dt * 0.1;
        }
    }

    public updateMovement(a: Agent, dt: number, engine: GameEngine) {
        // Use per-agent move speed WITH dynamic multiplier (Charge effect)
        a.moveProgress += a.moveSpeed * a.moveSpeedMult * dt;

        const c = HexUtils.toPx(a.q, a.r, engine.mapConfig);
        const nextHex = a.path[0];
        const n = HexUtils.toPx(nextHex.q, nextHex.r, engine.mapConfig);

        // Vertical interpolation logic can be handled in UnitRenderSystem, 
        // here we mostly care about X/Y transition for logic updates

        if (n.x > c.x) a.facing = 1;
        else if (n.x < c.x) a.facing = -1;

        a.px = HexUtils.lerp(c.x, n.x, a.moveProgress);
        a.py = HexUtils.lerp(c.y, n.y, a.moveProgress);

        if (a.moveProgress >= 1) {
            // Commit move
            engine.updateAgentPosition(a, nextHex.q, nextHex.r);

            a.isMoving = false;
            a.moveSpeedMult = 1.0; // Reset speed after step completes

            // Small nudge to separate stacked units visually if they glitch
            a.physics.vx -= a.facing * STACKING_RESOLUTION_FORCE; 
        }
    }

    public moveAgentToHex(a: Agent, targetHex: Hex, r: number, engine: GameEngine, speedMult: number = 1.0): NodeState {
        if (a.isMoving) {
            a.moveSpeedMult = speedMult; // Update dynamic speed
            a.setAnim(AnimState.MOVE);
            return NodeState.RUNNING;
        }

        // Check range (With Height Bonus)
        const effRange = this.getEffectiveRange(a, targetHex.q, targetHex.r, r, engine);
        if (HexUtils.dist(a, targetHex) <= effRange) {
            a.setAnim(AnimState.COMBAT_IDLE);
            return NodeState.SUCCESS;
        }

        // 1. Try Standard Pathfinding (Respecting Allies)
        let path = this.findPath(a, targetHex.q, targetHex.r, r, false, engine);

        // 2. Fallback: Ghost Pathfinding (Ignoring Allies)
        // If normal path failed, try to find a path ignoring units to see if "direction" exists
        if (path.length === 0) {
            path = this.findPath(a, targetHex.q, targetHex.r, r, true, engine); // true = ignoreUnits
        }

        if (path.length > 0) {
            const next = path[0];

            // CRITICAL CHECK: Even if we found a ghost path, is the IMMEDIATE NEXT STEP blocked?
            // Updated to pass movementType to isBlocked
            if (engine.isBlocked(next.q, next.r, a.id, a.movementType)) {
                // We know where we WANT to go, but it's blocked right now.
                // Instead of failing (which causes AI jitter/wandering), we WAIT.
                // This simulates "queueing" behind the frontline.
                a.setAnim(AnimState.COMBAT_IDLE); 
                // Return RUNNING to keep the AI node active, preventing re-calculation jitter
                return NodeState.RUNNING; 
            }

            a.path = [next];
            a.trajectory = path; // Visual only
            a.isMoving = true;
            a.moveProgress = 0;
            a.moveSpeedMult = speedMult;
            a.setAnim(AnimState.MOVE);

            // Physics Lean
            const dir = a.facing;
            a.physics.vx += dir * 2; 

            return NodeState.RUNNING;
        }

        // Truly unreachable (walled off)
        return NodeState.FAILURE;
    }

    public moveAgent(a: Agent, t: Agent, r: number, engine: GameEngine, speedMult: number = 1.0): NodeState {
        // When chasing a unit, we want to get within range R of them.
        // We don't necessarily need to step ON their tile.
        return this.moveAgentToHex(a, {q: t.q, r: t.r}, r, engine, speedMult);
    }

    public resolveStacking(engine: GameEngine) {
        this._stackingMap.clear();
        const map = this._stackingMap;

        engine.agents.forEach(a => {
            if (a.hp <= 0 || a.banished) return;
            const h = HexUtils.hash(a.q, a.r);
            if (!map.has(h)) map.set(h, []);
            map.get(h)!.push(a);
        });

        map.forEach((list, hash) => {
            if (list.length > 1) {
                const coords = HexUtils.unhash(hash);

                const stationary = list.filter(a => !a.isMoving);
                const keep = stationary.length > 0 ? stationary[0] : list[0];
                const toDisplace = list.filter(a => a !== keep);

                toDisplace.forEach(agent => {
                    const neighbors = HexUtils.neighbors(coords);
                    for (let i = neighbors.length - 1; i > 0; i--) {
                        const j = Math.floor(Math.random() * (i + 1));
                        [neighbors[i], neighbors[j]] = [neighbors[j], neighbors[i]];
                    }

                    let target = neighbors.find(n => engine.map.isValid(n.q, n.r) && !engine.map.isBlocked(n.q, n.r, engine, agent.id, agent.movementType));

                    // Fallback: Try valid but not obstacle (ignoring units)
                    if (!target) target = neighbors.find(n => engine.map.isValid(n.q, n.r) && !engine.map.hasObstacle(n.q, n.r));

                    if (target) {
                        engine.updateAgentPosition(agent, target.q, target.r);
                        // Cancel current move to allow physics drift to slide unit visually
                        if (agent.isMoving) {
                            agent.isMoving = false;
                            agent.path = [];
                        }
                    }
                });
            }
        });
    }

    // =========================================================================================
    // 🗺️ PATHFINDING (A* / Multi-Layer BFS)
    // =========================================================================================

    public findPath(
        startAgent: Agent, 
        endQ: number, 
        endR: number, 
        range: number,
        ignoreUnits: boolean, 
        engine: GameEngine
    ): Hex[] {
        const startH = HexUtils.hash(startAgent.q, startAgent.r);

        // Optimization: Pre-check if start satisfies range (using Height Bonus)
        const effRange = this.getEffectiveRange(startAgent, endQ, endR, range, engine);
        const startDist = HexUtils.dist({q: startAgent.q, r: startAgent.r}, {q: endQ, r: endR});
        if (startDist <= effRange) return [];

        this._pfCameFrom.clear();
        this._pfBlockers.clear();

        // 1. Populate Blockers
        // If ignoreUnits is TRUE (Ghost Mode), we only block Walls/Obstacles
        if (!ignoreUnits) {
            for (const a of engine.agents) {
                if (a.hp > 0 && !a.banished && a !== startAgent) {
                    const h = HexUtils.hash(a.q, a.r);
                    this._pfBlockers.add(h);

                    if (a.isMoving && a.path.length > 0) {
                        const hp = HexUtils.hash(a.path[0].q, a.path[0].r);
                        this._pfBlockers.add(hp);
                    }
                }
            }
        }

        let head = 0; 
        let tail = 0; 
        this._pfQueue[head++] = startH; 
        this._pfCameFrom.set(startH, -1); 

        let iterations = 0;
        let foundHash = -1;
        const targetHex = { q: endQ, r: endR };

        while (tail < head) {
            iterations++;
            if (iterations > PATHFINDING_MAX_ITERATIONS) break;

            const currentH = this._pfQueue[tail++]; 
            const currentHex = HexUtils.unhash(currentH);
            const currentTerrainH = engine.map.getTerrainHeight(currentHex.q, currentHex.r);

            // SUCCESS CONDITION: Inside Range? (Check height for this specific tile)
            const currentEffRange = this.getEffectiveRange(currentHex, targetHex.q, targetHex.r, range, engine);
            if (HexUtils.dist(currentHex, targetHex) <= currentEffRange) {
                foundHash = currentH;
                break;
            }

            for(let j = 0; j < 6; j++) {
                const offset = NEIGHBOR_HASH_OFFSETS[j];
                const nextH = currentH + offset;

                if (this._pfCameFrom.has(nextH)) continue;

                // Map Bounds Check
                if (!engine.map.isValidHash(nextH)) continue;

                // Static Obstacle Check
                // NEW: Flying Logic Check
                if (engine.map.hasObstacleHash(nextH)) {
                    // We need to check obstacle type
                    const obstacleTypeId = engine.map.obstacles.get(HexUtils.key(HexUtils.unhash(nextH)));
                    const obstacleDef = OBSTACLE_DB[obstacleTypeId || 'WALL'];

                    if (startAgent.movementType === MovementType.FLYING) {
                        // Flying units only blocked by specific "Sky Blockers" (like tall pillars)
                        if (obstacleDef?.blocksFlying) continue;
                    } else {
                        // Ground units blocked by standard "blocksMovement"
                        if (obstacleDef?.blocksMovement) continue;
                    }
                }

                // Dynamic Unit Check (Only if not ignoring units)
                if (!ignoreUnits && this._pfBlockers.has(nextH)) {
                    continue;
                }

                // --- TACTICS OGRE HEIGHT CHECK ---
                // Flying units IGNORE terrain height traversal costs
                if (startAgent.movementType !== MovementType.FLYING) {
                    const nextHexCoord = HexUtils.unhash(nextH);
                    const nextTerrainH = engine.map.getTerrainHeight(nextHexCoord.q, nextHexCoord.r);
                    const deltaH = Math.abs(nextTerrainH - currentTerrainH);

                    // Allow climb/drop if deltaH <= Jump Height (in pixels)
                    // Using max(1, jump) to ensure at least 1 block can be traversed by default
                    const maxClimb = Math.max(1, startAgent.jump) * BLOCK_HEIGHT;

                    if (deltaH > maxClimb) {
                        continue; // Too steep!
                    }
                }

                this._pfCameFrom.set(nextH, currentH);

                if (head < QUEUE_CAPACITY) {
                    this._pfQueue[head++] = nextH;
                }
            }
        }

        if (foundHash !== -1) {
            const path: Hex[] = [];
            let curr = foundHash;

            let sanity = 0;
            while (curr !== startH && sanity++ < 100) {
                path.push(HexUtils.unhash(curr));
                const prev = this._pfCameFrom.get(curr);
                if (prev === undefined || prev === -1) break;
                curr = prev;
            }
            return path.reverse();
        }

        return [];
    }

    // =========================================================================================
    // 🎯 TARGETING & TACTICS
    // =========================================================================================

    public updateTarget(a: Agent, engine: GameEngine) {
        if (a.target && (a.target.hp <= 0 || a.target.banished)) a.target = null;
        let minD = 999;
        let t: Agent | null = null;

        for (const o of engine.agents) {
            if (o.team !== a.team && o.hp > 0 && !o.banished) {
                const d = HexUtils.dist(a, o);
                if (d < minD) { minD = d; t = o; }
            }
        }
        a.target = t;
    }

    public calculateOptimalTarget(source: Agent, skill: any, engine: GameEngine): { targetAgent: Agent | null, targetHex: Hex | null } {
        if (skill.ccType === 'SILENCE' || skill.ccType2 === 'SILENCE') {
            const enemies = engine.agents.filter(a => 
                a.team !== source.team && a.hp > 0 && !a.banished && 
                HexUtils.dist(source, a) <= this.getEffectiveRange(source, a.q, a.r, skill.range, engine)
            );

            if (enemies.length > 0) {
                enemies.sort((a, b) => {
                    const score = (u: Agent) => {
                        if (u.castingSkillIdx === -1) return 0;
                        const s = u.skills[u.castingSkillIdx];
                        if (s?.tag === 'ULT') return 3;
                        if (s?.tag === 'ACTIVE') return 2;
                        return 1;
                    };
                    const sA = score(a);
                    const sB = score(b);
                    if (sA !== sB) return sB - sA;
                    return HexUtils.dist(source, a) - HexUtils.dist(source, b);
                });
                return { targetAgent: enemies[0], targetHex: null };
            }
        }

        if (skill.type === 'AOE') {
            const candidateHexes = new Set<number>();
            const radius = skill.aoeRadius || 1;
            // Rough search: Range + Radius + small buffer.
            // Exact check happens inside the loop using effective range.
            const searchDist = skill.range + 5; 

            engine.agents.forEach(enemy => {
                if (enemy.team !== source.team && enemy.hp > 0 && !enemy.banished) {
                    if (HexUtils.dist(source, enemy) <= searchDist) {
                        candidateHexes.add(HexUtils.hash(enemy.q, enemy.r));
                        HexUtils.neighbors(enemy).forEach(n => candidateHexes.add(HexUtils.hash(n.q, n.r)));
                    }
                }
            });

            let bestHex: Hex | null = null;
            let bestScore = -1;

            candidateHexes.forEach(hHash => {
                const h = HexUtils.unhash(hHash);
                if (!engine.map.isValid(h.q, h.r)) return;

                // Range Check: Can source cast to this ground position?
                const effRange = this.getEffectiveRange(source, h.q, h.r, skill.range, engine);
                if (HexUtils.dist(source, h) > effRange) return;

                let score = 0;
                let hitCount = 0;

                for (const target of engine.agents) {
                    if (target.hp <= 0 || target.banished) continue;

                    if (HexUtils.dist(h, target) <= radius) {
                        if (skill.power >= 0) {
                            if (target.team !== source.team) {
                                hitCount++;
                                score += 10;
                                if (target.castingSkillIdx !== -1) score += 5;
                            }
                        } else {
                            if (target.team === source.team) {
                                hitCount++;
                                score += 10;
                                if (target.hp < target.maxHp * 0.5) score += 5;
                            }
                        }
                    }
                }

                if (hitCount > 0 && score > bestScore) {
                    bestScore = score;
                    bestHex = h;
                }
            });

            if (bestHex) {
                return { targetAgent: null, targetHex: bestHex };
            }
        }

        let minD = 999;
        let t: Agent | null = null;
        for (const o of engine.agents) {
            if (o.team !== source.team && o.hp > 0 && !o.banished) {
                const d = HexUtils.dist(source, o);
                // Check against Height-Aware Range
                const effRange = this.getEffectiveRange(source, o.q, o.r, skill.range, engine);
                if (d <= effRange && d < minD) { minD = d; t = o; }
            }
        }
        return { targetAgent: t, targetHex: null };
    }
}
